#!/usr/bin/env python3
"""Render the two-option dynamic local game as a self-contained HTML audit."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--input-json",
        type=Path,
        default=Path(
            "data/processed/dynamic_local_game_v0_7/"
            "dynamic_local_game_v0_7.json"
        ),
    )
    parser.add_argument(
        "--output-html",
        type=Path,
        default=Path(
            "data/processed/dynamic_local_game_v0_7/"
            "dynamic_local_game_v0_7_audit.html"
        ),
    )
    return parser.parse_args()


HTML = r"""<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dynamic local defender game · v0.7</title><style>
:root{--bg:#071321;--panel:#101f32;--panel2:#14263c;--line:#304862;--text:#f3f7ff;--muted:#aebcd0;--cyan:#45e0d0;--pink:#ff51c7;--violet:#c58cff;--gold:#ffd052;--red:#ff6d5b;--blue:#438dff;--orange:#ff9c43;--green:#65dda0}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Pretendard,system-ui,sans-serif}main{max-width:1900px;margin:auto;padding:18px}h1,h2,h3{margin:0 0 8px}p{color:var(--muted);line-height:1.45}.notice{border-left:4px solid var(--gold);background:#192a42;padding:11px 14px;border-radius:7px;margin:10px 0}.controls{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:9px 0}.grow{flex:1}button{font:inherit;color:var(--text);background:#192b43;border:1px solid #4a6483;border-radius:8px;padding:8px 10px}button.active{border-color:var(--gold);color:var(--gold);background:#2a2940}.defenders{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.defenders button{text-align:left}.defenders small{display:block;color:var(--muted);margin-top:3px}.layout{display:grid;grid-template-columns:minmax(800px,1fr) 710px;gap:15px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:14px}.pitch{display:block;width:100%;background:#17743a;border-radius:9px}.scrub{width:100%}.time{font-variant-numeric:tabular-nums}.legend{display:flex;gap:12px;flex-wrap:wrap;color:#cbd6e6;font-size:.8rem;margin-top:8px}.sw{display:inline-block;width:19px;border-top:4px solid;margin-right:5px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.metric{background:#152a40;border-radius:8px;padding:8px;min-height:66px}.metric span{font-size:.69rem;color:var(--muted)}.metric strong{display:block;font-size:1rem;margin-top:4px}.box{background:var(--panel2);border:1px solid #2d445f;border-radius:9px;padding:10px;margin-top:9px}.small{font-size:.78rem;color:var(--muted)}.warn{color:#ffd082}.mode-table{width:100%;border-collapse:collapse;font-size:.75rem}.mode-table th,.mode-table td{padding:6px 4px;border-bottom:1px solid #304862;text-align:right}.mode-table th:first-child,.mode-table td:first-child{text-align:left}.mode-table tr{cursor:pointer}.mode-table tr.active{background:#203b55;outline:1px solid var(--gold)}.charts{display:grid;grid-template-columns:1fr 1fr;gap:8px}.chart{width:100%;height:auto;background:#0c1a2b;border-radius:7px}.focus{border-radius:99px;padding:5px 10px;background:#2a2940;color:var(--gold);font-weight:800}.formula{font-family:ui-monospace,SFMono-Regular,monospace;color:#d6e6ff}@media(max-width:1350px){.layout{grid-template-columns:1fr}}
</style></head><body><main><h1>Dynamic local defender game · v0.7</h1><p class="notice"><b>Framework-first 진단:</b> 같은 feasible 수비 궤적을 Klaus runner와 Kownacki carry의 <b>전체 시간축</b>에서 평가한다. 현재 비용은 moving goal-side geometry이며, 이후 동일한 행렬에 패스·carry·goal-access value를 교체한다.</p><div class="defenders"></div><div class="controls modes"></div><div class="layout"><section class="panel"><div class="controls"><button class="play">▶ 재생</button><span class="time"></span><span class="focus"></span><span class="grow"></span><span class="current"></span></div><svg class="pitch" viewBox="0 0 105 68"><rect width="105" height="68" fill="#17743a" stroke="white" stroke-width=".3"/><line x1="52.5" x2="52.5" y1="0" y2="68" stroke="white" stroke-width=".25"/><circle cx="52.5" cy="34" r="9.15" fill="none" stroke="white" stroke-width=".25"/><rect x="0" y="13.84" width="16.5" height="40.32" fill="none" stroke="white" stroke-width=".25"/><rect x="88.5" y="13.84" width="16.5" height="40.32" fill="none" stroke="white" stroke-width=".25"/><g class="static"></g><g class="moving"></g></svg><input class="scrub" type="range" min="0" value="0"><div class="legend"><span><i class="sw" style="border-color:var(--pink)"></i>Klaus runner</span><span><i class="sw" style="border-color:var(--violet)"></i>Kownacki carry</span><span><i class="sw" style="border-color:white;border-top-style:dashed"></i>실제 수비</span><span><i class="sw" style="border-color:var(--cyan)"></i>선택 수비</span><span><i class="sw" style="border-color:var(--orange);border-top-style:dashed"></i>Klaus moving target</span><span><i class="sw" style="border-color:var(--green);border-top-style:dashed"></i>Kownacki moving target</span></div><p class="small">현재 더 크게 열려 있는 옵션은 상단 배지와 굵은 연결선으로 표시된다. 수비가 한 옵션을 억제하면서 다른 옵션을 언제 놓치는지 본다.</p></section><aside class="panel"><h2 class="title"></h2><p class="subtitle"></p><div class="metrics"><div class="metric"><span>Klaus 평균 비용</span><strong class="runner-cost"></strong></div><div class="metric"><span>Kownacki 평균 비용</span><strong class="carry-cost"></strong></div><div class="metric"><span>Klaus 상대후회</span><strong class="runner-regret"></strong></div><div class="metric"><span>Kownacki 상대후회</span><strong class="carry-regret"></strong></div><div class="metric"><span>Klaus 억제 순위</span><strong class="runner-rank"></strong></div><div class="metric"><span>Carry 억제 순위</span><strong class="carry-rank"></strong></div><div class="metric"><span>Pareto 여부</span><strong class="pareto"></strong></div><div class="metric"><span>Pareto 경로 수</span><strong class="pareto-count"></strong></div></div><div class="box explanation"></div><div class="charts"><div class="box"><h3>시간별 억제 오차</h3><svg class="chart trace" viewBox="0 0 340 205"></svg><p class="small">분홍=Klaus, 보라=Kownacki. 낮을수록 잘 막는다.</p></div><div class="box"><h3>수비 경로 landscape</h3><svg class="chart scatter" viewBox="0 0 340 205"></svg><p class="small">x=Klaus 비용, y=Kownacki 비용. 왼쪽 아래가 좋고 금색은 Pareto다.</p></div></div><div class="box"><h3>경로 비교</h3><table class="mode-table"><thead><tr><th>수비 경로</th><th>Klaus</th><th>Carry</th><th>후회 max</th></tr></thead><tbody></tbody></table></div><p class="small warn">현재 attack re-selection은 두 행 중 더 억제되지 않은 옵션을 고르는 geometry 진단이다. 패스 라인과 P×G×A는 아직 사용하지 않는다.</p></aside></div></main><script id="data" type="application/json">__DATA__</script><script>
const S=JSON.parse(document.getElementById('data').textContent);let bi=0,mi=6,fi=0,playing=false,timer=null;const $=q=>document.querySelector(q),B=()=>S.branches[bi],M=()=>B().modes[mi],px=x=>52.5+S.attacking_direction*x,py=y=>34-y,fmt=v=>Number(v).toFixed(2);function interp(path,t){let p=[...path].sort((a,b)=>a[0]-b[0]);if(t<=p[0][0])return p[0].slice(1);if(t>=p[p.length-1][0])return p[p.length-1].slice(1);let j=p.findIndex(x=>x[0]>=t),a=p[j-1],b=p[j],f=(t-a[0])/(b[0]-a[0]);return[a[1]+f*(b[1]-a[1]),a[2]+f*(b[2]-a[2])]}function sampleAt(samples,t){if(t<=samples[0].time_s)return samples[0];if(t>=samples[samples.length-1].time_s)return samples[samples.length-1];let j=samples.findIndex(x=>x.time_s>=t),a=samples[j-1],b=samples[j],f=(t-a.time_s)/(b.time_s-a.time_s),o={};for(let k of Object.keys(a))o[k]=typeof a[k]==='number'?a[k]+f*(b[k]-a[k]):a[k];return o}function poly(path,color,dash='',width=.5,opacity=.95){return`<polyline points="${path.map(p=>`${px(p[1])},${py(p[2])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" stroke-dasharray="${dash}" opacity="${opacity}"/>`}
function defenders(){$('.defenders').innerHTML=S.branches.map((b,i)=>`<button data-bi="${i}" class="${i===bi?'active':''}"><b>${b.defender_name}</b><small>${b.feasible_response_count}개 feasible · ${b.pareto_response_count}개 Pareto</small></button>`).join('');document.querySelectorAll('.defenders button').forEach(x=>x.onclick=()=>{bi=Number(x.dataset.bi);mi=Math.min(6,B().modes.length-1);renderAll()})}function modes(){$('.modes').innerHTML='<b>동적 수비 목적</b>'+B().modes.map((m,i)=>`<button data-mi="${i}" class="${i===mi?'active':''}">${m.label}</button>`).join('');document.querySelectorAll('.modes button').forEach(x=>x.onclick=()=>{mi=Number(x.dataset.mi);renderAll()})}
function drawStatic(){let b=B(),m=M(),rt=m.summaries[0].samples.map(x=>[x.time_s,x.target_x,x.target_y]),ct=m.summaries[1].samples.map(x=>[x.time_s,x.target_x,x.target_y]);$('.static').innerHTML=poly(b.options[0].path_txy,'#ff51c7','',.62)+poly(b.options[1].path_txy,'#c58cff','',.68)+poly(b.modes[0].response.path_txy,'white','1 .55',.38,.8)+poly(m.response.path_txy,'#45e0d0','',.65)+poly(rt,'#ff9c43','1 .55',.38,.78)+poly(ct,'#65dda0','1 .55',.38,.78)}function frameAt(t){return S.background_frames.reduce((a,b)=>Math.abs(b.time_s-t)<Math.abs(a.time_s-t)?b:a)}
function drawCross(x,y,color,size=.68,width=.3){return`<line x1="${px(x)-size}" y1="${py(y)-size}" x2="${px(x)+size}" y2="${py(y)+size}" stroke="${color}" stroke-width="${width}"/><line x1="${px(x)-size}" y1="${py(y)+size}" x2="${px(x)+size}" y2="${py(y)-size}" stroke="${color}" stroke-width="${width}"/>`}function drawFrame(){let f=S.background_frames[fi],t=f.time_s,b=B(),m=M(),runner=interp(b.options[0].path_txy,Math.max(0,t)),carry=interp(b.options[1].path_txy,Math.max(0,t)),defender=interp(m.response.path_txy,Math.max(0,t)),actual=interp(b.modes[0].response.path_txy,Math.max(0,t)),rs=sampleAt(m.summaries[0].samples,Math.max(.2,t)),cs=sampleAt(m.summaries[1].samples,Math.max(.2,t)),rscale=Math.max(b.options[0].maximum_cost-b.options[0].minimum_cost,1e-9),cscale=Math.max(b.options[1].maximum_cost-b.options[1].minimum_cost,1e-9),rr=(rs.weighted_error_m-b.options[0].minimum_cost)/rscale,cr=(cs.weighted_error_m-b.options[1].minimum_cost)/cscale,focus=rr>=cr?0:1,hidden=[S.runner_id,S.ball_owner_id,b.defender_id],html=f.players.filter(p=>!hidden.includes(p[0])).map(p=>`<circle cx="${px(p[2])}" cy="${py(p[3])}" r=".67" fill="${p[1]===S.attacking_team_id?'#ff6d5b':'#438dff'}" stroke="white" stroke-width=".12"><title>${S.names[p[0]]||p[0]}</title></circle>`).join('');html+=`<circle cx="${px(runner[0])}" cy="${py(runner[1])}" r="1.0" fill="#ff51c7" stroke="white" stroke-width=".2"/><circle cx="${px(carry[0])}" cy="${py(carry[1])}" r="1.0" fill="#c58cff" stroke="white" stroke-width=".2"/><circle cx="${px(carry[0])}" cy="${py(carry[1])}" r=".32" fill="#111" stroke="white" stroke-width=".11"/>`;html+=`<circle cx="${px(actual[0])}" cy="${py(actual[1])}" r="1.12" fill="none" stroke="white" stroke-width=".3"/><circle cx="${px(defender[0])}" cy="${py(defender[1])}" r=".9" fill="#438dff" stroke="#45e0d0" stroke-width=".42"/>`;html+=drawCross(rs.target_x,rs.target_y,'#ff9c43')+drawCross(cs.target_x,cs.target_y,'#65dda0');let fs=focus===0?rs:cs,fc=focus===0?'#ff9c43':'#65dda0';html+=`<line x1="${px(defender[0])}" y1="${py(defender[1])}" x2="${px(fs.target_x)}" y2="${py(fs.target_y)}" stroke="${fc}" stroke-width=".35" stroke-dasharray=".55 .3"/>`;$('.moving').innerHTML=html;$('.scrub').value=fi;$('.time').textContent=`t=${t>=0?'+':''}${t.toFixed(2)}초`;$('.focus').textContent=`공격 재선택: ${focus===0?S.runner_name:S.ball_owner_name}`;$('.current').innerHTML=`현재 오차 <b>${fmt(rs.weighted_error_m)} / ${fmt(cs.weighted_error_m)}m</b>`;traceChart()}
function details(){let b=B(),m=M(),r=m.option_regrets;$('.title').textContent=`${b.defender_name} · ${m.label}`;$('.subtitle').innerHTML=`${m.selection_rule}<br>현재 경로에서 raw worst는 <b>${b.options[m.raw_worst_option_index].label}</b>, relative-regret worst는 <b>${b.options[m.regret_worst_option_index].label}</b>`;$('.runner-cost').textContent=fmt(m.option_costs[0])+'m';$('.carry-cost').textContent=fmt(m.option_costs[1])+'m';$('.runner-regret').textContent=(100*r[0]).toFixed(0)+'%';$('.carry-regret').textContent=(100*r[1]).toFixed(0)+'%';$('.runner-rank').textContent=`${m.option_ranks[0]}/${b.feasible_response_count}`;$('.carry-rank').textContent=`${m.option_ranks[1]}/${b.feasible_response_count}`;$('.pareto').textContent=m.is_pareto?'예':'아니오';$('.pareto-count').textContent=b.pareto_response_count;let explain={dynamic_runner:'Klaus의 미래 goal-side target을 시간 전체에서 가장 잘 통제한다. 그 대가로 Kownacki carry가 얼마나 열리는지 본다.',dynamic_carry:'Kownacki carry의 미래 앞공간을 시간 전체에서 가장 잘 통제한다. 그 대가로 Klaus가 얼마나 열리는지 본다.',dynamic_local_minimax:'두 옵션의 raw geometry 비용 중 더 큰 값을 최소화한다. 단위는 같지만 출발 난이도가 큰 옵션에 끌릴 수 있다.',dynamic_compromise:'각 옵션별 최적 경로에서 얼마나 손해 보았는지를 0–1로 정규화하고, 더 큰 후회를 최소화한다.',actual:'관측된 실제 수비 궤적을 같은 두 동적 목적에 사후 평가한다.',existing_runner:'v0.5의 runner-follow 경로를 새 동적 행렬에서 재평가한다.',existing_endpoint:'v0.5의 고정 carry endpoint 경로를 새 동적 행렬에서 재평가한다.'};$('.explanation').innerHTML=`<h3>해석</h3>${explain[m.key]||''}`;$('.mode-table tbody').innerHTML=b.modes.map((x,i)=>`<tr data-mi="${i}" class="${i===mi?'active':''}"><td>${x.label}</td><td>${fmt(x.option_costs[0])}</td><td>${fmt(x.option_costs[1])}</td><td>${(100*Math.max(...x.option_regrets)).toFixed(0)}%</td></tr>`).join('');document.querySelectorAll('.mode-table tbody tr').forEach(x=>x.onclick=()=>{mi=Number(x.dataset.mi);renderAll()});scatterChart()}
function traceChart(){let m=M(),rows=m.summaries,max=Math.max(...rows.flatMap(x=>x.samples.map(s=>s.weighted_error_m)),1),left=32,right=328,top=15,bottom=168,t0=.2,t1=S.horizon_seconds,x=t=>left+(t-t0)/(t1-t0)*(right-left),y=v=>bottom-v/max*(bottom-top),html=`<line x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}" stroke="#6f8198"/><line x1="${left}" y1="${top}" x2="${left}" y2="${bottom}" stroke="#6f8198"/>`;rows.forEach((row,i)=>{html+=`<polyline points="${row.samples.map(s=>`${x(s.time_s)},${y(s.weighted_error_m)}`).join(' ')}" fill="none" stroke="${i===0?'#ff51c7':'#c58cff'}" stroke-width="2.2"/>`});let t=Math.max(t0,S.background_frames[fi].time_s);html+=`<line x1="${x(t)}" y1="${top}" x2="${x(t)}" y2="${bottom}" stroke="#ffd052"/><text x="2" y="${top+5}" fill="#aebcd0" font-size="10">${max.toFixed(1)}</text><text x="${left}" y="195" fill="#aebcd0" font-size="10">0.2s</text><text x="${right-24}" y="195" fill="#aebcd0" font-size="10">${t1.toFixed(1)}s</text>`;$('.trace').innerHTML=html}
function scatterChart(){let b=B(),pts=b.response_points,xmin=Math.min(...pts.map(p=>p.runner_cost)),xmax=Math.max(...pts.map(p=>p.runner_cost)),ymin=Math.min(...pts.map(p=>p.carry_cost)),ymax=Math.max(...pts.map(p=>p.carry_cost)),left=35,right=328,top=14,bottom=170,x=v=>left+(v-xmin)/Math.max(xmax-xmin,1e-9)*(right-left),y=v=>bottom-(v-ymin)/Math.max(ymax-ymin,1e-9)*(bottom-top),html=`<line x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}" stroke="#6f8198"/><line x1="${left}" y1="${top}" x2="${left}" y2="${bottom}" stroke="#6f8198"/>`;pts.forEach(p=>html+=`<circle cx="${x(p.runner_cost)}" cy="${y(p.carry_cost)}" r="${p.is_pareto?2.3:1.25}" fill="${p.is_pareto?'#ffd052':'#70829a'}" opacity="${p.is_pareto ? 0.9 : 0.35}"/>`);let m=M();html+=`<circle cx="${x(m.option_costs[0])}" cy="${y(m.option_costs[1])}" r="4" fill="#45e0d0" stroke="white" stroke-width="1.2"/><text x="${left}" y="197" fill="#ff9cdb" font-size="10">Klaus →</text><text x="2" y="${top+6}" fill="#c58cff" font-size="10">Carry</text>`;$('.scatter').innerHTML=html}
function renderAll(){defenders();modes();drawStatic();details();drawFrame()}function init(){fi=Math.max(0,S.background_frames.findIndex(f=>f.time_s>=0));$('.scrub').max=S.background_frames.length-1;$('.scrub').oninput=e=>{fi=Number(e.target.value);drawFrame()};$('.play').onclick=e=>{playing=!playing;e.target.textContent=playing?'❚❚ 일시정지':'▶ 재생';if(playing)timer=setInterval(()=>{fi=fi>=S.background_frames.length-1?Math.max(0,S.background_frames.findIndex(f=>f.time_s>=0)):fi+1;drawFrame()},70);else clearInterval(timer)};renderAll()}init();
</script></body></html>"""


def main() -> None:
    args = parse_args()
    data = json.loads(args.input_json.read_text(encoding="utf-8"))
    html = HTML.replace(
        "__DATA__", json.dumps(data, ensure_ascii=False).replace("</", "<\/")
    )
    args.output_html.parent.mkdir(parents=True, exist_ok=True)
    args.output_html.write_text(html, encoding="utf-8")
    print(f"output: {args.output_html.resolve()}")


if __name__ == "__main__":
    main()
